// Quantas paginas existem: o proprio Chatwoot responde, no meta.all_count
// da primeira chamada. Era aqui que estava o furo — a versao anterior
// varria 20 paginas fixas e, como o Chatwoot devolve da mais recente para
// a mais antiga, o historico parava dez dias atras.
const cfg = $('Resolver caixa').first().json;
const r = $json || {};
const meta = (r.data && r.data.meta) || r.meta || {};
const lista = (r.data && r.data.payload) || r.payload || [];

const total = Number(meta.all_count || 0);
if (!total) {
  throw new Error('O Chatwoot nao informou o total de conversas da caixa "'
    + cfg.caixaNome + '". Confira a credencial e o id da conta.');
}
// O tamanho da pagina vem observado, nao chutado: se um dia o Chatwoot
// mudar de 25 para outro numero, a conta continua certa.
const porPagina = lista.length || 25;
const TETO = 600;

const ultimaPagina = Math.min(Math.ceil(total / porPagina), TETO);
const fim = cfg.paginasMax > 0
  ? Math.min(cfg.paginaInicial + cfg.paginasMax - 1, ultimaPagina)
  : ultimaPagina;

const paginas = [];
for (let p = cfg.paginaInicial; p <= fim; p++) {
  paginas.push({ json: {
    pagina: p,
    url: cfg.urlBase + '&page=' + p,
    trazerMensagens: cfg.trazerMensagens,
    corte: cfg.corte,
    mapaCaixas: cfg.mapaCaixas,
    total, ultimaPagina, caixaNome: cfg.caixaNome,
  } });
}
if (!paginas.length) {
  throw new Error('PAGINA_INICIAL (' + cfg.paginaInicial + ') passou da ultima pagina ('
    + ultimaPagina + ') da caixa "' + cfg.caixaNome + '".');
}
return paginas;

// ── O QUE AJUSTAR AQUI — e so aqui ───────────────────────────────
//
// CAIXA: qual caixa de entrada varrer. '' (vazio) = todas.
//   Vale o nome como aparece no Chatwoot ('2. Antigo', '1. Oficial') ou
//   so um pedaco dele ('antigo'). Comece pela Antigo, que e a que tem os
//   contatos que ainda nao estao no nosso banco.
//
// CRIADO_ANTES: 'AAAA-MM-DD' traz so as conversas criadas antes dessa
//   data; '' traz todas. E o mesmo filtro "Criado em / e menos que" da
//   tela do Chatwoot.
//
// TRAZER_MENSAGENS: false = so a lista de conversas e a agenda de
//   contatos (rapido). true = traz tambem as mensagens, e ai e UMA
//   chamada por conversa: use com PAGINAS_MAX para ir em blocos.
//
// PAGINA_INICIAL / PAGINAS_MAX: 1 e 0 varrem tudo. Para ir em blocos,
//   PAGINAS_MAX = 20 e va avancando PAGINA_INICIAL: 1, 21, 41...
const CAIXA = '2. Antigo';
const CRIADO_ANTES = '';
const TRAZER_MENSAGENS = false;
const PAGINA_INICIAL = 1;
const PAGINAS_MAX = 0;

const BASE = 'https://chat.suplelive.com.br/api/v1/accounts/1/conversations'
           + '?status=all&assignee_type=all';

const r = $json || {};
const caixas = r.payload || r.data || [];
const nomes = caixas.map(i => i.name || '').filter(Boolean);

let caixaId = '', caixaNome = 'todas as caixas';
if (String(CAIXA).trim()) {
  const alvo = String(CAIXA).trim().toLowerCase();
  const achada = caixas.find(i => String(i.name || '').toLowerCase() === alvo)
              || caixas.find(i => String(i.name || '').toLowerCase().indexOf(alvo) >= 0);
  if (!achada) {
    throw new Error('Nao achei a caixa "' + CAIXA + '". As que existem: ' + (nomes.join(' | ') || 'nenhuma'));
  }
  caixaId = String(achada.id);
  caixaNome = achada.name;
}

// O corte por data e feito depois, ao converter: o endpoint de listagem
// do Chatwoot nao aceita filtro de data — so a tela dele aceita.
let corte = 0;
if (String(CRIADO_ANTES).trim()) {
  corte = Date.parse(String(CRIADO_ANTES).trim() + 'T00:00:00Z');
  if (!corte) throw new Error('CRIADO_ANTES precisa ser AAAA-MM-DD (ex.: 2026-08-30).');
}

const url = BASE + (caixaId ? ('&inbox_id=' + caixaId) : '');
// Os nomes das caixas viajam junto para o Converter nao ter que pedi-los
// de novo — sao os mesmos para a varredura inteira.
const mapaCaixas = {};
caixas.forEach(i => { mapaCaixas[i.id] = i.name || ''; });

return [{ json: {
  caixaId, caixaNome, mapaCaixas, corte,
  trazerMensagens: TRAZER_MENSAGENS,
  paginaInicial: PAGINA_INICIAL,
  paginasMax: PAGINAS_MAX,
  urlBase: url,
  urlContagem: url + '&page=1',
} }];

// Cada conversa do Chatwoot vira DUAS coisas: o registro que o WhatsLive
// desenha na caixa e o contato que vai para a agenda. O formato e o mesmo
// do fluxo ao vivo, para historico e mensagem nova ficarem indistinguiveis.
const saida = [];
for (const item of $input.all()) {
  const cfg = item.json || {};
  const caixas = cfg.mapaCaixas || {};
  const corte = Number(cfg.corte || 0);
  const r = cfg;
  const lista = (r.data && r.data.payload) || r.payload || [];

  for (const c of lista) {
    const num = c.id;                    // display_id da conversa
    if (!num) continue;

    let criada = Number(c.created_at || 0);
    if (criada && criada < 1e12) criada = criada * 1000;
    // O mesmo "Criado em / e menos que" da tela do Chatwoot, feito aqui
    // porque o endpoint de listagem nao aceita filtro de data.
    if (corte && criada && criada >= corte) continue;

    const contato = (c.meta && c.meta.sender) || {};
    const ultima = c.last_non_activity_message || {};
    const mtU = ultima.message_type;
    const deU = ultima.private === true ? 'nota'
              : (mtU === 1 || mtU === 3 || mtU === 'outgoing' || mtU === 'template') ? 'agente'
              : 'cliente';
    let ts = (c.timestamp || c.last_activity_at || ultima.created_at || 0);
    if (ts && ts < 1e12) ts = ts * 1000;
    let texto = String(ultima.content || '').trim();
    if (!texto && Array.isArray(ultima.attachments) && ultima.attachments.length) {
      const tipos = { image: 'imagem', audio: 'audio', video: 'video', file: 'arquivo' };
      texto = '[' + (tipos[ultima.attachments[0].file_type] || 'anexo') + ']';
    }

    const tel = String(contato.phone_number || '').trim();
    const digitos = tel.replace(/\D/g, '');
    const cpf = String((contato.custom_attributes && contato.custom_attributes.cpf) || '')
      .replace(/\D/g, '');
    const caixa = caixas[c.inbox_id] || '';

    saida.push({ json: {
      convId: 'cw_' + num,
      convNum: num,
      trazerMensagens: cfg.trazerMensagens !== false,
      conv: {
        id: 'cw_' + num,
        nome: contato.name || 'Contato',
        telefone: tel,
        caixa,
        ultima: texto.slice(0, 120),
        deUltima: deU,
        ts: ts || Date.now(),
      },
      contato: {
        nome: contato.name || 'Contato',
        telefone: tel,
        digitos,
        cpf: cpf.length === 11 ? cpf : '',
        criadoEm: criada || ts || Date.now(),
        caixa,
      },
    } });
  }
}
return saida;

// As conversas sobem em blocos de 200 numa chamada so — uma por uma
// seriam milhares de chamadas e a varredura levaria horas.
const BLOCO = 200;
const todas = $input.all().map(i => i.json.conv).filter(c => c && c.id);
const saida = [];
for (let i = 0; i < todas.length; i += BLOCO) {
  const mapa = {};
  todas.slice(i, i + BLOCO).forEach(c => { mapa[c.id] = c; });
  saida.push({ json: { corpo: mapa, quantas: Object.keys(mapa).length } });
}
return saida.length ? saida : [{ json: { corpo: {}, quantas: 0 } }];

// Sem mensagens pedidas, a varredura para aqui: as conversas ja foram
// gravadas e o Inbox ja mostra todo mundo com a ultima fala.
return $input.all().filter(i => i.json.trazerMensagens);

// Mesma classificacao do fluxo ao vivo — cliente, agente e a NOTA
// interna (o cadeado), que e como o envio de template pelo Gupshup fica
// registrado. Historico e mensagem nova precisam ficar iguais na tela.
const saida = [];
const entradas = $input.all();
for (let i = 0; i < entradas.length; i++) {
  const r = entradas[i].json || {};
  const lista = r.payload || (r.data && r.data.payload) || [];
  let convId = '';
  try { convId = $('So quem quer mensagens').all()[i].json.convId; } catch (e) {}
  if (!convId || !lista.length) continue;

  const mapa = {};
  for (const m of lista) {
    const mt = m.message_type;
    const deCliente = mt === 0 || mt === 'incoming';
    const ehTemplate = mt === 3 || mt === 'template';
    const deAgente = mt === 1 || mt === 'outgoing' || ehTemplate;
    if (!deCliente && !deAgente) continue;          // atividade do sistema
    const privada = m.private === true;

    let texto = String(m.content || '').trim();
    const anexos = Array.isArray(m.attachments) ? m.attachments : [];
    if (!texto && anexos.length) {
      const tipos = { image: 'imagem', audio: 'audio', video: 'video', file: 'arquivo' };
      texto = '[' + (tipos[anexos[0].file_type] || 'anexo') + ']';
    }
    if (!texto) continue;
    // O eco da persona e os comandos internos nao viram balao
    if (deAgente && !privada && texto.indexOf('*Manoel - Suplelive:*') === 0) continue;
    if (deAgente && !privada && texto[0] === '/') continue;

    let ts = m.created_at || 0;
    if (ts && ts < 1e12) ts = ts * 1000;
    const quem = (((m.sender && m.sender.name) || '?').trim().split(/\s+/)[0]);
    mapa['m' + m.id] = {
      texto: texto.slice(0, 4000),
      de: privada ? 'nota' : (deAgente ? 'agente' : 'cliente'),
      autor: privada ? quem : (deAgente ? ('Manoel (' + quem + ')') : ''),
      ts: ts || Date.now(),
    };
  }
  if (Object.keys(mapa).length) saida.push({ json: { convId, corpo: mapa, quantas: Object.keys(mapa).length } });
}
return saida;

// O placar da varredura. Agora ele sabe o tamanho do alvo, entao da para
// conferir de olho se veio tudo — e nao ficar adivinhando se falta pagina.
let conversas = 0, mensagens = 0, falhas = 0, total = 0, paginas = 0;
try {
  const p = $('Paginas a varrer').all();
  paginas = p.length;
  total = Number(p[0].json.total || 0);
} catch (e) {}
try { $('Agrupar conversas').all().forEach(i => { conversas += (i.json.quantas || 0); }); } catch (e) {}
try { $('Converter mensagens').all().forEach(i => { mensagens += (i.json.quantas || 0); }); } catch (e) {}
let contatos = 0, caixa = '';
try { $('Montar agenda').all().forEach(i => { contatos += (i.json.quantas || 0); }); } catch (e) {}
try { caixa = $('Paginas a varrer').first().json.caixaNome || ''; } catch (e) {}
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.ok === false || j.erro) falhas++;
}

// Com corte por data, vir menos que o total e o esperado — nao e falha.
let cortou = false, bloco = false;
try {
  const cfg = $('Resolver caixa').first().json;
  cortou = !!cfg.corte;
  bloco = cfg.paginasMax > 0 || cfg.paginaInicial > 1;
} catch (e) {}
const faltou = total && !cortou && !bloco && conversas < total - 5;
return [{ json: {
  caixa,
  totalNoChatwoot: total,
  paginasVarridas: paginas,
  conversas,
  contatos,
  mensagens,
  falhas,
  recado: !conversas
    ? 'Nenhuma conversa voltou — confira a credencial do Chatwoot.'
    : (faltou
      ? ('Vieram ' + conversas + ' de ' + total + ' conversas. Faltou gente: rode de novo, '
         + 'ou quebre em blocos com PAGINA_INICIAL / PAGINAS_MAX no no "Resolver caixa".')
      : ((bloco ? 'Bloco concluido' : 'Varredura completa') + ' da caixa "' + caixa + '": ' + conversas + ' conversa(s) de '
         + total + ', ' + contatos + ' contato(s) na agenda e ' + mensagens
         + ' mensagem(ns). Nao precisa rodar de novo.')),
} }];

// A agenda: cada conversa varrida carrega um contato, e e ele que o
// pedido "alimentar nosso novo banco de dados" quer guardar.
//
// O id sai do telefone, nao do relogio: 'wct_5527999987802'. Assim rodar
// a varredura duas vezes reescreve o MESMO registro em vez de encher a
// agenda de gente repetida — e o mesmo contato visto na caixa Antigo e na
// Oficial vira um so.
const BLOCO = 200;
const quem = 'varredura do Chatwoot';

const porTelefone = {};
for (const item of $input.all()) {
  const c = (item.json || {}).contato;
  if (!c || !c.digitos || c.digitos.length < 10) continue;
  const id = 'wct_' + c.digitos;
  const ja = porTelefone[id];
  // Entre duas visitas ao mesmo numero, fica a mais completa: nome de
  // verdade ganha de "Contato", e quem tem CPF ganha de quem nao tem.
  if (ja) {
    const melhorNome = (!ja.nome || ja.nome === 'Contato') && c.nome && c.nome !== 'Contato';
    const ganhouCpf = !ja.cpf && c.cpf;
    if (!melhorNome && !ganhouCpf) continue;
  }
  const partes = String(c.nome || 'Contato').trim().split(/\s+/);
  const nome = (partes.shift() || 'Contato').slice(0, 40);
  porTelefone[id] = {
    id,
    nome,
    sobrenome: partes.join(' ').slice(0, 40),
    telefone: c.telefone,
    cpf: c.cpf || '',
    criadoEm: c.criadoEm || Date.now(),
    criadoPor: quem,
    caixa: c.caixa || '',
  };
}

const ids = Object.keys(porTelefone);
const saida = [];
for (let i = 0; i < ids.length; i += BLOCO) {
  const mapa = {};
  ids.slice(i, i + BLOCO).forEach(k => { mapa[k] = porTelefone[k]; });
  saida.push({ json: { corpo: mapa, quantas: Object.keys(mapa).length } });
}
return saida.length ? saida : [{ json: { corpo: {}, quantas: 0 } }];
